<?php
defined('ABSPATH') || exit;
class SMF_Courier_Operations {
 public static function init(){add_action('admin_menu',array(__CLASS__,'menu'),35);add_action('admin_post_smf_save_courier_ops',array(__CLASS__,'save'));}
 public static function menu(){add_submenu_page('sync-meta-flow','Courier Operations','Courier Operations','manage_woocommerce','smf-courier-operations',array(__CLASS__,'page'));}
 private static function settings(){return array('default_provider'=>sanitize_key((string)get_option('smf_courier_provider','generic')),'risk_window'=>max(1,min(365,absint(get_option('smf_courier_risk_window',90)))),'processing_sla'=>max(1,min(1440,absint(get_option('smf_courier_processing_sla',15)))),'delivery_sla'=>max(1,min(720,absint(get_option('smf_courier_delivery_sla',72))));}
 private static function status_key($s){$s=strtolower(sanitize_key((string)$s));if(in_array($s,array('completed','smf-delivered','delivered'),true))return'delivered';if(in_array($s,array('smf-returned','refunded','returned'),true))return'returned';if(in_array($s,array('cancelled','failed'),true))return'cancelled';if(in_array($s,array('smf-shipped','shipped'),true))return'shipped';if($s==='smf-confirmed'||$s==='confirmed')return'confirmed';return'other';}
 public static function risk_score($stats){$o=max(0,(int)($stats['orders']??0));$d=max(0,(int)($stats['delivered']??0));$r=max(0,(int)($stats['returned']??0));$c=max(0,(int)($stats['cancelled']??0));$score=50;if($o>0)$score=50+($d/$o)*40-($r/$o)*60-($c/$o)*30;$score=max(0,min(100,round($score)));return array('score'=>$score,'label'=>$score>=75?'LOW RISK':($score>=45?'MEDIUM RISK':'HIGH RISK'));}
 public static function customer_risk($order_id){$o=wc_get_order(absint($order_id));if(!$o)return array('score'=>0,'label'=>'Unknown','orders'=>0,'delivered'=>0,'returned'=>0,'cancelled'=>0);$email=sanitize_email($o->get_billing_email());$phone=preg_replace('/\D+/','',(string)$o->get_billing_phone());$window=self::settings()['risk_window'];$since=gmdate('Y-m-d H:i:s',time()-$window*DAY_IN_SECONDS);$a=array('limit'=>100,'return'=>'ids','exclude'=>array($o->get_id()),'date_created'=>'>='.$since);if($email)$a['billing_email']=$email;elseif($phone)$a['billing_phone']=$phone;else return array('score'=>0,'label'=>'Unknown','orders'=>0,'delivered'=>0,'returned'=>0,'cancelled'=>0);$ids=wc_get_orders($a);$st=array('orders'=>0,'delivered'=>0,'returned'=>0,'cancelled'=>0);foreach($ids as $id){$prev=wc_get_order($id);if(!$prev)continue;$st['orders']++;$k=self::status_key($prev->get_status());if($k==='delivered')$st['delivered']++;elseif($k==='returned')$st['returned']++;elseif($k==='cancelled')$st['cancelled']++;}$risk=self::risk_score($st);return array_merge($st,$risk);}
 public static function recommend_provider($o){$p=self::settings()['default_provider'];$r=self::customer_risk($o->get_id());$intel=self::provider_intelligence(30);if($p==='generic'&&!empty($intel)){$best=$intel[0];$p=$best['provider'];$reason='Best observed provider health score: '.$best['health_score'].'/100';}else{$reason=$p!=='generic'?'Configured default provider':($r['label']==='HIGH RISK'?'High-risk customer: review before dispatch':'No native provider selected');}return array('provider'=>$p,'risk'=>$r,'reason'=>$reason);}
 private static function orders_window($days){return wc_get_orders(array('limit'=>200,'type'=>'shop_order','date_created'=>'>='.gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS),'orderby'=>'date','order'=>'DESC','return'=>'objects'));}
 private static function provider_stats($days){global $wpdb;$t=$wpdb->prefix.'smf_courier_events';$since=gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS);$r=$wpdb->get_results($wpdb->prepare("SELECT provider,COUNT(*) events,SUM(result='processed') processed,SUM(result='failed') failed FROM $t WHERE received_at >= %s GROUP BY provider ORDER BY events DESC",$since),ARRAY_A);return$r?:array();}
 private static function delivery_rows($days){global $wpdb;SMF_Courier_Timeline::ensure_table();$days=max(1,min(365,absint($days)));$since=gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS);$t=$wpdb->prefix.'smf_courier_events';$sql=$wpdb->prepare("SELECT provider,order_id,status,received_at,result FROM $t WHERE received_at >= %s AND order_id IS NOT NULL AND result='processed' AND status IN ('smf-shipped','shipped','smf-delivered','delivered','completed','smf-returned','returned','refunded','cancelled','failed') ORDER BY order_id ASC,received_at ASC,id ASC",$since);return $wpdb->get_results($sql,ARRAY_A)?:array();}
 public static function delivery_intelligence($days=30){$s=self::settings();$rows=self::delivery_rows($days);$orders=array();foreach($rows as $row){$oid=(int)$row['order_id'];if(!$oid)continue;$provider=sanitize_key((string)$row['provider'])?:'generic';if(!isset($orders[$oid]))$orders[$oid]=array('provider'=>$provider,'shipped'=>null,'delivered'=>null,'returned'=>null,'cancelled'=>null);if($provider!=='generic')$orders[$oid]['provider']=$provider;$k=self::status_key($row['status']);$ts=strtotime((string)$row['received_at']);if(!$ts)continue;if($k==='shipped'&&$orders[$oid]['shipped']===null)$orders[$oid]['shipped']=$ts;elseif($k==='delivered'&&$orders[$oid]['delivered']===null)$orders[$oid]['delivered']=$ts;elseif($k==='returned'&&$orders[$oid]['returned']===null)$orders[$oid]['returned']=$ts;elseif($k==='cancelled'&&$orders[$oid]['cancelled']===null)$orders[$oid]['cancelled']=$ts;}
 $out=array();$ids_by_provider=array();foreach($orders as $oid=>$o){$p=$o['provider'];if(!isset($out[$p]))$out[$p]=array('provider'=>$p,'orders'=>0,'delivered'=>0,'returned'=>0,'cancelled'=>0,'delivery_sla_breaches'=>0,'delivery_hours_total'=>0,'delivery_samples'=>0,'return_hours_total'=>0,'return_samples'=>0,'delivered_value'=>0.0,'returned_value'=>0.0,'cancelled_value'=>0.0,'sla_breach_value'=>0.0);$out[$p]['orders']++;$order=wc_get_order($oid);$total=$order?(float)$order->get_total():0.0;if($o['delivered']!==null){$out[$p]['delivered']++;$out[$p]['delivered_value']+=$total;if($o['shipped']!==null&&$o['delivered']>=$o['shipped']){$hours=($o['delivered']-$o['shipped'])/3600;$out[$p]['delivery_hours_total']+=$hours;$out[$p]['delivery_samples']++;if($hours>$s['delivery_sla']){$out[$p]['delivery_sla_breaches']++;$out[$p]['sla_breach_value']+=$total;}}}if($o['returned']!==null){$out[$p]['returned']++;$out[$p]['returned_value']+=$total;if($o['delivered']!==null&&$o['returned']>=$o['delivered']){$out[$p]['return_hours_total']+=(($o['returned']-$o['delivered'])/3600);$out[$p]['return_samples']++;}}elseif($o['cancelled']!==null){$out[$p]['cancelled']++;$out[$p]['cancelled_value']+=$total;}}
 foreach($out as &$r){$r['avg_delivery_hours']=$r['delivery_samples']?round($r['delivery_hours_total']/$r['delivery_samples'],1):0;$r['avg_return_hours']=$r['return_samples']?round($r['return_hours_total']/$r['return_samples'],1):0;$r['delivery_sla_rate']=$r['delivery_samples']?round(($r['delivery_sla_breaches']/$r['delivery_samples'])*100,1):0;$r['delivered_value']=round($r['delivered_value'],2);$r['returned_value']=round($r['returned_value'],2);$r['cancelled_value']=round($r['cancelled_value'],2);$r['sla_breach_value']=round($r['sla_breach_value'],2);$realized=$r['delivered_value'];$adverse=$r['returned_value']+$r['cancelled_value'];$value_base=$realized+$adverse;$delivery_score=$r['orders']?($r['delivered']/$r['orders'])*100:100;$adverse_score=$value_base>0?max(0,100-($adverse/$value_base)*100):100;$sla_score=max(0,100-$r['delivery_sla_rate']);$r['financial_score']=(int)round(($delivery_score*.45)+($adverse_score*.35)+($sla_score*.20));$r['financial_label']=$r['financial_score']>=80?'STRONG':($r['financial_score']>=60?'WATCH':'WEAK');$r['impact_value']=round($r['returned_value']+$r['cancelled_value']+$r['sla_breach_value'],2);unset($r['delivery_hours_total'],$r['delivery_samples'],$r['return_hours_total'],$r['return_samples']);}unset($r);usort($out,function($a,$b){return $b['financial_score']<=>$a['financial_score'];});return array_values($out);}
 public static function provider_intelligence($days=30){global $wpdb;SMF_Courier_Timeline::ensure_table();$s=self::settings();$days=max(1,min(365,absint($days)));$since=gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS);$t=$wpdb->prefix.'smf_courier_events';$rows=$wpdb->get_results($wpdb->prepare("SELECT provider,COUNT(*) events,SUM(result='processed') processed,SUM(result='failed') failed,SUM(attempts>1) retried,AVG(CASE WHEN processed_at IS NOT NULL AND received_at IS NOT NULL THEN GREATEST(0,TIMESTAMPDIFF(SECOND,received_at,processed_at)) ELSE NULL END) processing_seconds,SUM(CASE WHEN processed_at IS NOT NULL AND received_at IS NOT NULL AND TIMESTAMPDIFF(MINUTE,received_at,processed_at)>%d THEN 1 ELSE 0 END) sla_breaches FROM $t WHERE received_at >= %s GROUP BY provider ORDER BY events DESC",$s['processing_sla'],$since),ARRAY_A);$delivery=self::delivery_intelligence($days);$delivery_map=array();foreach($delivery as $d)$delivery_map[$d['provider']]=$d;$out=array();foreach($rows?:array() as $r){$events=max(0,(int)$r['events']);$processed=max(0,(int)$r['processed']);$failed=max(0,(int)$r['failed']);$retried=max(0,(int)$r['retried']);$success=$events?($processed/$events)*100:100;$retry_rate=$events?($retried/$events)*100:0;$avg=(float)$r['processing_seconds'];$latency_score=$avg<=0?100:max(0,100-(($avg/($s['processing_sla']*60))*100));$failure_score=max(0,100-(($failed/max(1,$events))*100));$retry_score=max(0,100-(($retry_rate*2)));$sla_score=$events?max(0,100-(((int)$r['sla_breaches']/$events)*100)):100;$health=(int)round(($success*.35)+($latency_score*.25)+($retry_score*.20)+($sla_score*.20));$d=$delivery_map[(string)$r['provider']]??array('orders'=>0,'delivered'=>0,'returned'=>0,'cancelled'=>0,'delivery_sla_breaches'=>0,'delivery_sla_rate'=>0,'avg_delivery_hours'=>0,'avg_return_hours'=>0,'delivered_value'=>0,'returned_value'=>0,'cancelled_value'=>0,'sla_breach_value'=>0,'impact_value'=>0,'financial_score'=>100,'financial_label'=>'STRONG');$combined=(int)round(($health*.60)+($d['financial_score']*.40));$out[]=array_merge(array('provider'=>(string)$r['provider'],'events'=>$events,'processed'=>$processed,'failed'=>$failed,'retried'=>$retried,'success_rate'=>round($success,1),'retry_rate'=>round($retry_rate,1),'avg_processing_seconds'=>round($avg,1),'sla_breaches'=>(int)$r['sla_breaches'],'health_score'=>max(0,min(100,$health)),'health_label'=>$health>=80?'HEALTHY':($health>=60?'WATCH':'DEGRADED'),'combined_score'=>$combined,'combined_label'=>$combined>=80?'STRONG':($combined>=60?'WATCH':'WEAK')),array('delivery_orders'=>(int)$d['orders'],'delivered'=>(int)$d['delivered'],'returned'=>(int)$d['returned'],'cancelled'=>(int)$d['cancelled'],'delivery_sla_breaches'=>(int)$d['delivery_sla_breaches'],'delivery_sla_rate'=>(float)$d['delivery_sla_rate'],'avg_delivery_hours'=>(float)$d['avg_delivery_hours'],'avg_return_hours'=>(float)$d['avg_return_hours'],'delivered_value'=>(float)$d['delivered_value'],'returned_value'=>(float)$d['returned_value'],'cancelled_value'=>(float)$d['cancelled_value'],'sla_breach_value'=>(float)$d['sla_breach_value'],'impact_value'=>(float)$d['impact_value'],'financial_score'=>(int)$d['financial_score'],'financial_label'=>$d['financial_label']));}
 foreach($delivery as $d){if(isset($delivery_map[$d['provider']])&&array_filter($out,function($x)use($d){return $x['provider']===$d['provider'];}))continue;$out[]=array_merge(array('provider'=>$d['provider'],'events'=>0,'processed'=>0,'failed'=>0,'retried'=>0,'success_rate'=>100,'retry_rate'=>0,'avg_processing_seconds'=>0,'sla_breaches'=>0,'health_score'=>100,'health_label'=>'HEALTHY'),array('delivery_orders'=>(int)$d['orders'],'delivered'=>(int)$d['delivered'],'returned'=>(int)$d['returned'],'cancelled'=>(int)$d['cancelled'],'delivery_sla_breaches'=>(int)$d['delivery_sla_breaches'],'delivery_sla_rate'=>(float)$d['delivery_sla_rate'],'avg_delivery_hours'=>(float)$d['avg_delivery_hours'],'avg_return_hours'=>(float)$d['avg_return_hours'],'delivered_value'=>(float)$d['delivered_value'],'returned_value'=>(float)$d['returned_value'],'cancelled_value'=>(float)$d['cancelled_value'],'sla_breach_value'=>(float)$d['sla_breach_value'],'impact_value'=>(float)$d['impact_value'],'financial_score'=>(int)$d['financial_score'],'financial_label'=>$d['financial_label'],'combined_score'=>(int)round(100*.6+$d['financial_score']*.4),'combined_label'=>$d['financial_score']>=80?'STRONG':($d['financial_score']>=60?'WATCH':'WEAK')));}
 usort($out,function($a,$b){return $b['combined_score']<=>$a['combined_score'];});return$out;}
 public static function combined_risk($order_id){$risk=self::customer_risk($order_id);$provider=self::provider_intelligence(30);$p=$provider?$provider[0]:array('health_score'=>100,'combined_score'=>100,'provider'=>'generic');$combined=(int)round(($risk['score']*.55)+((int)$p['combined_score']*.45));return array('customer_score'=>(int)$risk['score'],'customer_label'=>$risk['label'],'provider'=>$p['provider'],'courier_health'=>(int)$p['health_score'],'courier_financial_score'=>(int)$p['financial_score'],'courier_combined_score'=>(int)$p['combined_score'],'combined_score'=>$combined,'combined_label'=>$combined>=75?'LOW RISK':($combined>=50?'MEDIUM RISK':'HIGH RISK'));}
 private static function queue(){ $out=array();$intel=self::provider_intelligence(30);$best=$intel? $intel[0]:null;foreach(self::orders_window(30) as $o){$k=self::status_key($o->get_status());if(!in_array($k,array('confirmed','shipped'),true)||$o->get_meta('_smf_tracking_number'))continue;$risk=self::customer_risk($o->get_id());$p=self::settings()['default_provider'];if($p==='generic'&&$best)$p=$best['provider'];$reason=$p!=='generic'?'Configured/observed provider':'No native provider selected';$out[]=array('id'=>$o->get_id(),'date'=>$o->get_date_created()?$o->get_date_created()->date_i18n('Y-m-d H:i'):'','total'=>$o->get_total(),'status'=>$o->get_status(),'risk'=>$risk,'provider'=>$p,'reason'=>$reason);if($risk['label']==='HIGH RISK')$out[count($out)-1]['reason']='High-risk customer: review before dispatch';}return$out;}
 public static function save(){if(!current_user_can('manage_woocommerce'))wp_die('Unauthorized');check_admin_referer('smf_save_courier_ops');update_option('smf_courier_risk_window',max(1,min(365,absint($_POST['risk_window']??90))),false);update_option('smf_courier_processing_sla',max(1,min(1440,absint($_POST['processing_sla']??15))),false);update_option('smf_courier_delivery_sla',max(1,min(720,absint($_POST['delivery_sla']??72))),false);wp_safe_redirect(admin_url('admin.php?page=smf-courier-operations&updated=1'));exit;}
 private static function money($v){return number_format_i18n((float)$v,2);}
 public static function page(){if(!current_user_can('manage_woocommerce'))return;$s=self::settings();$q=self::queue();$p=self::provider_stats($s['risk_window']);$intel7=self::provider_intelligence(7);$intel30=self::provider_intelligence(30);$intel90=self::provider_intelligence(90);?><div class="wrap smf-wrap smf-settings"><div class="smf-header"><div><h1>Courier Operations</h1><p>Dispatch queue, customer-risk signals, delivery SLA, financial impact and provider intelligence.</p></div><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=sync-meta-flow'));?>">← Dashboard</a></div><div class="smf-panel"><h2>Risk & SLA policy</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="smf_save_courier_ops"><?php wp_nonce_field('smf_save_courier_ops');?><p><label>Risk history (days)<br><input class="small-text" type="number" min="1" max="365" name="risk_window" value="<?php echo esc_attr($s['risk_window']);?>"></label> <label>Processing SLA (minutes)<br><input class="small-text" type="number" min="1" max="1440" name="processing_sla" value="<?php echo esc_attr($s['processing_sla']);?>"></label> <label>Delivery SLA (hours)<br><input class="small-text" type="number" min="1" max="720" name="delivery_sla" value="<?php echo esc_attr($s['delivery_sla']);?>"></label></p><?php submit_button('Save Policy');?></form><p class="smf-muted">SLA values are merchant-configurable thresholds, not claims about a courier's contractual promise. Delivery SLA is measured from the first recorded shipped event to the first recorded delivered event for an order.</p></div><div class="smf-panel"><h2>Provider delivery & financial intelligence · 7 / 30 / 90 days</h2><?php foreach(array(7=>$intel7,30=>$intel30,90=>$intel90) as $days=>$rows):?><h3><?php echo esc_html($days);?> days</h3><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Provider</th><th>Delivered</th><th>Avg delivery</th><th>SLA breaches</th><th>Returned</th><th>Cancelled</th><th>Delivered value</th><th>Impact value</th><th>Financial</th><th>Combined</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="10">No courier delivery data recorded.</td></tr><?php else:foreach($rows as $r):?><tr><td><?php echo esc_html(ucfirst($r['provider']));?></td><td><?php echo esc_html($r['delivered']);?></td><td><?php echo esc_html($r['avg_delivery_hours']);?>h</td><td><?php echo esc_html($r['delivery_sla_breaches']);?> (<?php echo esc_html($r['delivery_sla_rate']);?>%)</td><td><?php echo esc_html($r['returned']);?></td><td><?php echo esc_html($r['cancelled']);?></td><td><?php echo esc_html(self::money($r['delivered_value']));?></td><td><?php echo esc_html(self::money($r['impact_value']));?></td><td><strong><?php echo esc_html($r['financial_label']);?></strong> · <?php echo esc_html($r['financial_score']);?>/100</td><td><strong><?php echo esc_html($r['combined_label']);?></strong> · <?php echo esc_html($r['combined_score']);?>/100</td></tr><?php endforeach;endif;?></tbody></table></div><?php endforeach;?><p class="smf-muted">Impact value is the sum of returned/cancelled order value plus delivered order value that breached the configured delivery SLA. It is an operational impact proxy, not profit or contractual damages.</p></div><div class="smf-panel"><h2>Provider operational health · 7 / 30 / 90 days</h2><?php foreach(array(7=>$intel7,30=>$intel30,90=>$intel90) as $days=>$rows):?><h3><?php echo esc_html($days);?> days</h3><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Provider</th><th>Events</th><th>Success</th><th>Retry</th><th>Avg processing</th><th>Processing SLA</th><th>Health</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7">No courier events recorded.</td></tr><?php else:foreach($rows as $r):?><tr><td><?php echo esc_html(ucfirst($r['provider']));?></td><td><?php echo esc_html($r['events']);?></td><td><?php echo esc_html($r['success_rate']);?>%</td><td><?php echo esc_html($r['retry_rate']);?>%</td><td><?php echo esc_html($r['avg_processing_seconds']);?>s</td><td><?php echo esc_html($r['sla_breaches']);?></td><td><strong><?php echo esc_html($r['health_label']);?></strong> · <?php echo esc_html($r['health_score']);?>/100</td></tr><?php endforeach;endif;?></tbody></table></div><?php endforeach;?></div><div class="smf-panel"><h2>Dispatch queue <span class="smf-muted">(last 30 days)</span></h2><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th><th>Risk</th><th>Provider</th><th>Reason</th></tr></thead><tbody><?php if(!$q):?><tr><td colspan="7">No confirmed/shipped orders are waiting for courier tracking.</td></tr><?php else:foreach($q as $r):?><tr><td><a href="<?php echo esc_url(admin_url('post.php?post='.$r['id'].'&action=edit'));?>">#<?php echo esc_html($r['id']);?></a></td><td><?php echo esc_html($r['date']);?></td><td><?php echo esc_html(number_format_i18n((float)$r['total'],2));?></td><td><?php echo esc_html(wc_get_order_status_name($r['status']));?></td><td><strong><?php echo esc_html($r['risk']['label']);?></strong> · <?php echo esc_html($r['risk']['score']);?>/100</td><td><?php echo esc_html(ucfirst($r['provider']));?></td><td><?php echo esc_html($r['reason']);?></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="smf-panel"><h2>Legacy webhook performance</h2><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Provider</th><th>Events</th><th>Processed</th><th>Failed</th></tr></thead><tbody><?php if(!$p):?><tr><td colspan="4">No courier events recorded in this window.</td></tr><?php else:foreach($p as $r):?><tr><td><?php echo esc_html(ucfirst($r['provider']));?></td><td><?php echo esc_html($r['events']);?></td><td><?php echo esc_html($r['processed']);?></td><td><?php echo esc_html($r['failed']);?></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="smf-panel"><h2>Routing & financial policy</h2><p class="smf-muted">When no provider is configured, the highest combined operational/financial score observed over the last 30 days is suggested. Customer risk is combined with courier health and financial quality for dispatch context; no automatic shipment is created.</p></div></div><?php }
}
